                i += 1;
            }
            return i;
        }
        if ((c == 45) || ((c >= 48) && (c <= 57))) {
            i += 1;
            while ((i < n) && ((emon.Port.BlobU8(b, i) >= 48) && (emon.Port.BlobU8(b, i) <= 57))) {
                i += 1;
            }
            if (EdInt(t, b, st, i) == 0) {
                return 0 - EdFail(t, TbInteger(), st);
            }
            return i;
        }
        return 0 - EdFail(t, TbUnexpected(), i);
    }
    internal static int EdField(emon.Transcriptctx.Tr t, byte[] b, int mapAt, int code) {
        // Where the value of the first key `code` (`tf`) of the map at `map-at` starts, or -1: the first of a repeated key wins, a key not in `tf` is passed.
        int i = EdWs(b, mapAt) + 1;
        while (0 < 1) {
            i = EdWs(b, i);
            if ((i >= emon.Port.BlobLen(b)) || (emon.Port.BlobU8(b, i) == 125)) {
                return -1;
            }
            int ke = EdEnd(t, b, i, 0);
            int ks = TfFind(b, i + 1, ke);
            int vs = EdWs(b, ke);
            int ve = EdEnd(t, b, vs, 0);
            if (ks == code) {
                return vs;
            }
            i = ve;
        }
        return -1;
    }
    internal static int EdFirst(byte[] b, int pos) {
        // The first byte of the value at `pos` (whitespace first), or -1 at the end.
        int i = EdWs(b, pos);
        if (i >= emon.Port.BlobLen(b)) {
            return -1;
        }
        return emon.Port.BlobU8(b, i);
    }
    internal static int EdIsInt(byte[] b, int pos) {
        // 1 when the value at `pos` is an integer.
        int c = EdFirst(b, pos);
        if ((c == 45) || ((c >= 48) && (c <= 57))) {
            return 1;
        }
        return 0;
    }
    internal static int EdIntAt(emon.Transcriptctx.Tr t, byte[] b, int pos) {
        // The integer at `pos` into `ival`: 1, or 0 when the value is no integer.
        if (EdIsInt(b, pos) == 0) {
            return 0;
        }
        int st = EdWs(b, pos);
        int e = EdEnd(t, b, st, 0);
        return EdInt(t, b, st, e);
    }
    internal static int EdCp(byte[] b, int i) {
        // The code point whose UTF-8 starts at byte `i` (the blob is valid UTF-8).
        int c = emon.Port.BlobU8(b, i);
        if (c < 128) {
            return c;
        }
        if (c < 224) {
            return ((c & 31) << (6)) | (emon.Port.BlobU8(b, i + 1) & 63);
        }
        if (c < 240) {
            return ((c & 15) << (12)) | (((emon.Port.BlobU8(b, i + 1) & 63) << (6)) | (emon.Port.BlobU8(b, i + 2) & 63));
        }
        return ((c & 7) << (18)) | (((emon.Port.BlobU8(b, i + 1) & 63) << (12)) | (((emon.Port.BlobU8(b, i + 2) & 63) << (6)) | (emon.Port.BlobU8(b, i + 3) & 63)));
    }
    internal static int EdCpLen(byte[] b, int i) {
        // How many bytes the UTF-8 sequence at `i` takes.
        int c = emon.Port.BlobU8(b, i);
        if (c < 128) {
            return 1;
        }
        if (c < 224) {
            return 2;
        }
        if (c < 240) {
            return 3;
        }
        return 4;
    }
    internal static int EdSpanPush(byte[] b, int from, int to, emon.Port.Cells dst) {
        // Push the code points of the bytes from..to to `dst`. Answers how many.
        int i = from;
        int k = 0;
        while (i < to) {
            emon.Port.CellsPush(dst, EdCp(b, i));
            k += 1;
            i += EdCpLen(b, i);
        }
        return k;
    }
    internal static int EdStrPush(byte[] b, int pos, emon.Port.Cells dst) {
        // Push the code points of the string at `pos` to `dst`, a backslash taking the next character as it is. Answers how many.
        int st = EdWs(b, pos);
        int i = st + 1;
        int k = 0;
        while (emon.Port.BlobU8(b, i) != 34) {
            if (emon.Port.BlobU8(b, i) == 92) {
                i += 1;
            }
            emon.Port.CellsPush(dst, EdCp(b, i));
            k += 1;
            i += EdCpLen(b, i);
        }
        return k;
    }
    internal static int EdInts(emon.Transcriptctx.Tr t, byte[] b, int pos) {
        // Push the integers of the vector at `pos` to `tmp`; answers how many, or -1 when the value is no vector of integers.
        if (EdFirst(b, pos) != 91) {
            return -1;
        }
        int i = EdWs(b, pos) + 1;
        int k = 0;
        while (0 < 1) {
            i = EdWs(b, i);
            if (emon.Port.BlobU8(b, i) == 93) {
                return k;
            }
            if (EdIntAt(t, b, i) == 0) {
                return -1;
            }
            emon.Port.CellsPush(t.Tmp, t.Ival);
            k += 1;
            i = EdEnd(t, b, i, 0);
        }
        return k;
    }
    internal static int EdAddEntry(emon.Transcriptctx.Tr t, int round, int bm, int rlen, int alen) {
        // Append the entry whose request and answer are in `tmp` (the request first) to `ents`.
        int n = t.Nents;
        emon.Port.CellsPush(t.Ents, 6 + (rlen + alen));
        emon.Port.CellsPush(t.Ents, round);
        emon.Port.CellsPush(t.Ents, bm);
        emon.Port.CellsPush(t.Ents, 0);
        emon.Port.CellsPush(t.Ents, n);
        emon.Port.CellsPush(t.Ents, rlen);
        int i = 0;
        while (i < (rlen + alen)) {
            int v = emon.Port.CellsAt(t.Tmp, i);
            emon.Port.CellsPush(t.Ents, v);
            i += 1;
        }
        t.Nents = n + 1;
        return 0;
    }
    internal static int EdProducer(emon.Transcriptctx.Tr t, byte[] b, int pos) {
        // The `:producer` map at `pos`: the pairs whose value is a string, in the order the file has them. A producer that is no map is passed.
        if (EdFirst(b, pos) != 123) {
            return 0;
        }
        int i = EdWs(b, pos) + 1;
        while (0 < 1) {
            i = EdWs(b, i);
            if (emon.Port.BlobU8(b, i) == 125) {
                return 0;
            }
            int ke = EdEnd(t, b, i, 0);
            int vs = EdWs(b, ke);
            int ve = EdEnd(t, b, vs, 0);
            if (emon.Port.BlobU8(b, vs) == 34) {
                int p0 = emon.Port.CellsLen(t.Prod);
                emon.Port.CellsPush(t.Prod, 0);
                int kn = EdSpanPush(b, i + 1, ke, t.Prod);
                emon.Port.CellsSet(t.Prod, p0, kn);
                int p1 = emon.Port.CellsLen(t.Prod);
                emon.Port.CellsPush(t.Prod, 0);
                int vn = EdStrPush(b, vs, t.Prod);
                emon.Port.CellsSet(t.Prod, p1, vn);
            }
            i = ve;
        }
        return 0;
    }
    internal static int EdInputs(emon.Transcriptctx.Tr t, byte[] b, int pos) {
        // The `:inputs` vector at `pos`: each a map with an `:index` and a `:length`. 0, or the reason (`tb`).
        if (EdFirst(b, pos) != 91) {
            return EdFail(t, TbNoInputs(), EdWs(b, pos));
        }
        int i = EdWs(b, pos) + 1;
        while (0 < 1) {
            i = EdWs(b, i);
            if (emon.Port.BlobU8(b, i) == 93) {
                return 0;
            }
            if (emon.Port.BlobU8(b, i) != 123) {
                return EdFail(t, TbInputMap(), i);
            }
            int ip = EdField(t, b, i, TfIndex());
            if ((ip < 0) || (EdIntAt(t, b, ip) == 0)) {
                return EdFail(t, TbInputIndex(), i);
            }
            int index = t.Ival;
            int lp = EdField(t, b, i, TfLength());
            if ((lp < 0) || (EdIntAt(t, b, lp) == 0)) {
                return EdFail(t, TbInputLength(), i);
            }
            emon.Port.CellsPush(t.Inputs, index);
            emon.Port.CellsPush(t.Inputs, t.Ival);
            i = EdEnd(t, b, i, 0);
        }
        return 0;
    }
    internal static int EdEntry(emon.Transcriptctx.Tr t, byte[] b, int at) {
        // The entry map at `at`: checked as the hosts always checked it (the order of the checks is theirs), and appended. 0, or the reason (`tb`).
        int rp = EdField(t, b, at, TfRound());
        if ((rp < 0) || (EdIntAt(t, b, rp) == 0)) {
            return EdFail(t, TbEntryRound(), at);
        }
        int round = t.Ival;
        int kp = EdField(t, b, at, TfKind());
        if ((kp < 0) || (EdFirst(b, kp) != 58)) {
            return EdFail(t, TbEntryKind(), at);
        }
        int ks = EdWs(b, kp);
        int kind = TkFind(b, ks + 1, EdEnd(t, b, ks, 0));
        if (kind < 0) {
            return EdFail(t, TbEntryKind(), at);
        }
        emon.Port.CellsDrop(t.Tmp, 0);
        int qp = EdField(t, b, at, TfReq());
        if (qp < 0) {
            return EdFail(t, TbEntryReq(), at);
        }
        int rlen = EdInts(t, b, qp);
        if (rlen < 0) {
            return EdFail(t, TbEntryReq(), at);
        }
        int ap = EdField(t, b, at, TfAns());
        if (ap < 0) {
            return EdFail(t, TbEntryAns(), at);
        }
        int alen = EdInts(t, b, ap);
        if (alen < 0) {
            return EdFail(t, TbEntryAns(), at);
        }
        if ((rlen < 3) || ((emon.Port.CellsAt(t.Tmp, 0) != rlen) || (emon.Port.CellsAt(t.Tmp, 1) != kind))) {
            return EdFail(t, TbReqRecord(), at);
        }
        if ((alen < 4) || ((emon.Port.CellsAt(t.Tmp, rlen) != alen) || ((emon.Port.CellsAt(t.Tmp, rlen + 1) != kind) || (emon.Port.CellsAt(t.Tmp, rlen + 2) != emon.Port.CellsAt(t.Tmp, 2))))) {
            return EdFail(t, TbAnsRecord(), at);
        }
        int bp = EdField(t, b, at, TfBitmap());
        int bm = 0;
        if ((bp >= 0) && (EdFirst(b, bp) == 34)) {
            bm = emon.Port.CellsLen(t.Names) + 1;
            emon.Port.CellsPush(t.Names, 0);
            int nn = EdStrPush(b, bp, t.Names);
            emon.Port.CellsSet(t.Names, bm - 1, nn);
        }
        return EdAddEntry(t, round, bm, rlen, alen);
    }
    internal static int EdEntries(emon.Transcriptctx.Tr t, byte[] b, int pos) {
        // The `:entries` vector at `pos`. 0, or the reason (`tb`).
        if (EdFirst(b, pos) != 91) {
            return EdFail(t, TbNoEntries(), EdWs(b, pos));
        }
        int i = EdWs(b, pos) + 1;
        while (0 < 1) {
            i = EdWs(b, i);
            if (emon.Port.BlobU8(b, i) == 93) {
                return 0;
            }
            if (emon.Port.BlobU8(b, i) != 123) {
                return EdFail(t, TbEntryMap(), i);
            }
            int r = EdEntry(t, b, i);
            if (r != 0) {
                return r;
            }
            i = EdEnd(t, b, i, 0);
        }
        return 0;
    }
    public static int TrRead(emon.Transcriptctx.Tr t, byte[] b) {
        // Read `transcript.edn` from `b` into `t` (a new one): 0, or the reason it is no transcript (`tb`), its sentence in `msg`.
        if (EdUtf8(b) == 0) {
            return EdFail(t, TbNotUtf8(), 0);
        }
        int e = EdEnd(t, b, 0, 0);
        if (e < 0) {
            return t.Why;
        }
        int f = EdWs(b, e);
        if (f != emon.Port.BlobLen(b)) {
            return EdFail(t, TbTrailing(), f);
        }
        int top = EdWs(b, 0);
        if (emon.Port.BlobU8(b, top) != 123) {
            return EdFail(t, TbNotMap(), top);
        }
        int vp = EdField(t, b, top, TfVersion());
        int pp = EdField(t, b, top, TfProducer());
        int ip = EdField(t, b, top, TfInputs());
        int ep = EdField(t, b, top, TfEntries());
        if ((vp < 0) || (EdIntAt(t, b, vp) == 0)) {
            return EdFail(t, TbVersion(), top);
        }
        if (t.Ival != 1) {
            return EdFail(t, TbVersion(), top);
        }
        if (pp >= 0) {
            EdProducer(t, b, pp);
        }
        if (ip < 0) {
            return EdFail(t, TbNoInputs(), top);
        }
        int r = EdInputs(t, b, ip);
        if (r != 0) {
            return r;
        }
        if (ep < 0) {
            return EdFail(t, TbNoEntries(), top);
        }
        return EdEntries(t, b, ep);
    }
    public static int TrAddInput(emon.Transcriptctx.Tr t, int index, int length) {
        // An input of the run: its index and its length, never its bytes.
        emon.Port.CellsPush(t.Inputs, index);
        emon.Port.CellsPush(t.Inputs, length);
        return 0;
    }
    public static int TrAddProducer(emon.Transcriptctx.Tr t, emon.Port.Cells key, emon.Port.Cells val) {
        // One name/value of WHO ANSWERED (D214), each a run of code points. The file writes them escaped (`tr-write`); a name is written as it is.
        int kn = emon.Port.CellsLen(key);
        int vn = emon.Port.CellsLen(val);
        int i = 0;
        emon.Port.CellsPush(t.Prod, kn);
        while (i < kn) {
            int v = emon.Port.CellsAt(key, i);
            emon.Port.CellsPush(t.Prod, v);
            i += 1;
        }
        emon.Port.CellsPush(t.Prod, vn);
        i = 0;
        while (i < vn) {
            int v = emon.Port.CellsAt(val, i);
            emon.Port.CellsPush(t.Prod, v);
            i += 1;
        }
        return 0;
    }
    public static int TrAddEntry(emon.Transcriptctx.Tr t, int round, emon.Port.Cells src, int reqAt, int reqLen, int ansAt, int ansLen, int bitmap) {
        // An entry: the round, the request record at `req-at` of `src`, the answer record at `ans-at`, and whether it has a bitmap (the host keeps the pixels).
        emon.Port.CellsDrop(t.Tmp, 0);
        int i = 0;
        while (i < reqLen) {
            int v = emon.Port.CellsAt(src, reqAt + i);
            emon.Port.CellsPush(t.Tmp, v);
            i += 1;
        }
        i = 0;
        while (i < ansLen) {
            int v = emon.Port.CellsAt(src, ansAt + i);
            emon.Port.CellsPush(t.Tmp, v);
            i += 1;
        }
        if (bitmap == 0) {
            return EdAddEntry(t, round, 0, reqLen, ansLen);
        }
        return EdAddEntry(t, round, -1, reqLen, ansLen);
    }
    internal static int TwInts(System.Text.StringBuilder @out, emon.Port.Cells c, int from, int n) {
        // `[a b c]`.
        int i = 0;
        emon.Port.TextAscii(@out, "[");
        while (i < n) {
            if (i > 0) {
                emon.Port.TextAscii(@out, " ");
            }
            emon.Port.TextI32(@out, emon.Port.CellsAt(c, from + i));
            i += 1;
        }
        emon.Port.TextAscii(@out, "]");
        return n;
    }
    internal static int TwCps(System.Text.StringBuilder @out, emon.Port.Cells c, int from, int n, int escape) {
        // The code points of a name or a value. ESCAPED (a value in the file): a backslash is written `/` and a double quote `'`, so the file's string
        // needs no escape of its own and a reader never sees one (D214).
        int i = 0;
        while (i < n) {
            int v = emon.Port.CellsAt(c, from + i);
            if ((escape == 1) && (v == 92)) {
                v = 47;
            }
            if ((escape == 1) && (v == 34)) {
                v = 39;
            }
            emon.Port.TextCp(@out, v);
            i += 1;
        }
        return n;
    }
    public static int TrBitmapName(int n, System.Text.StringBuilder @out) {
        // The name of the file a bitmap is written to, from its entry's place: `bitmap-0000.png`.
        emon.Port.TextAscii(@out, "bitmap-");
        if (n < 1000) {
            emon.Port.TextAscii(@out, "0");
        }
        if (n < 100) {
            emon.Port.TextAscii(@out, "0");
        }
        if (n < 10) {
            emon.Port.TextAscii(@out, "0");
        }
        emon.Port.TextI32(@out, n);
        emon.Port.TextAscii(@out, ".png");
        return n;
    }
    public static int TrWrite(emon.Transcriptctx.Tr t, System.Text.StringBuilder @out) {
        // Write `transcript.edn` (FORMAT VERSION 1) to `out`: the same bytes on every host for the same entries.
        emon.Port.TextAscii(@out, "{:");
        TfEmitName(@out, TfVersion());
        emon.Port.TextAscii(@out, " 1");
        emon.Port.TextCp(@out, 10);
        if (emon.Port.CellsLen(t.Prod) > 0) {
            emon.Port.TextAscii(@out, " :");
            TfEmitName(@out, TfProducer());
            emon.Port.TextAscii(@out, " {");
            int n = emon.Port.CellsLen(t.Prod);
            int at = 0;
            while (at < n) {
                int kn = emon.Port.CellsAt(t.Prod, at);
                int vn = emon.Port.CellsAt(t.Prod, at + (kn + 1));
                if (at > 0) {
                    emon.Port.TextAscii(@out, " ");
                }
                emon.Port.TextAscii(@out, ":");
                TwCps(@out, t.Prod, at + 1, kn, 0);
                emon.Port.TextAscii(@out, " ");
                emon.Port.TextCp(@out, 34);
                TwCps(@out, t.Prod, at + (kn + 2), vn, 1);
                emon.Port.TextCp(@out, 34);
                at += kn + (vn + 2);
            }
            emon.Port.TextAscii(@out, "}");
            emon.Port.TextCp(@out, 10);
        }
        emon.Port.TextAscii(@out, " :");
        TfEmitName(@out, TfInputs());
        emon.Port.TextAscii(@out, " [");
        int n = emon.Port.CellsLen(t.Inputs);
        int at = 0;
        while (at < n) {
            if (at > 0) {
                emon.Port.TextAscii(@out, " ");
            }
            emon.Port.TextAscii(@out, "{:");
            TfEmitName(@out, TfIndex());
            emon.Port.TextAscii(@out, " ");
            emon.Port.TextI32(@out, emon.Port.CellsAt(t.Inputs, at));
            emon.Port.TextAscii(@out, " :");
            TfEmitName(@out, TfLength());
            emon.Port.TextAscii(@out, " ");
            emon.Port.TextI32(@out, emon.Port.CellsAt(t.Inputs, at + 1));
            emon.Port.TextAscii(@out, "}");
            at += 2;
        }
        emon.Port.TextAscii(@out, "]");
        emon.Port.TextCp(@out, 10);
        emon.Port.TextAscii(@out, " :");
        TfEmitName(@out, TfEntries());
        emon.Port.TextAscii(@out, " [");
        int en = emon.Port.CellsLen(t.Ents);
        int e = 0;
        while (e < en) {
            int rl = emon.Port.CellsAt(t.Ents, e + 5);
            int al = emon.Port.CellsAt(t.Ents, e) - (6 + rl);
            emon.Port.TextCp(@out, 10);
            emon.Port.TextAscii(@out, "  {:");
            TfEmitName(@out, TfRound());
            emon.Port.TextAscii(@out, " ");
            emon.Port.TextI32(@out, emon.Port.CellsAt(t.Ents, e + 1));
            emon.Port.TextAscii(@out, " :");
            TfEmitName(@out, TfKind());
            emon.Port.TextAscii(@out, " :");
            int known = 0;
            if (rl > 1) {
                known = TkEmitName(@out, emon.Port.CellsAt(t.Ents, e + 7));
            }
            if (known == 0) {
                emon.Port.TextAscii(@out, "unknown");
            }
            emon.Port.TextAscii(@out, " :");
            TfEmitName(@out, TfReq());
            emon.Port.TextAscii(@out, " ");
            TwInts(@out, t.Ents, e + 6, rl);
            emon.Port.TextAscii(@out, " :");
            TfEmitName(@out, TfAns());
            emon.Port.TextAscii(@out, " ");
            TwInts(@out, t.Ents, e + (6 + rl), al);
            if (emon.Port.CellsAt(t.Ents, e + 2) != 0) {
                emon.Port.TextAscii(@out, " :");
                TfEmitName(@out, TfBitmap());
                emon.Port.TextAscii(@out, " ");
                emon.Port.TextCp(@out, 34);
                TrBitmapName(emon.Port.CellsAt(t.Ents, e + 4), @out);
                emon.Port.TextCp(@out, 34);
            }
            emon.Port.TextAscii(@out, "}");
            e += emon.Port.CellsAt(t.Ents, e);
        }
        emon.Port.TextAscii(@out, "]}");
        emon.Port.TextCp(@out, 10);
        return 0;
    }
    internal static int TrHash(emon.Port.Cells c, int at, int cnt) {
        // A hash of the `cnt` cells at `at`, below 2^25 (no step overflows an I32).
        int h = 17;
        int i = 0;
        while (i < cnt) {
            int v = emon.Port.CellsAt(c, at + i);
            h = ((h * 31) + ((v & 1048575) + (((v) >> (20)) & 4095))) & 33554431;
            i += 1;
        }
        return h;
    }
    internal static int TrKeyEq(emon.Port.Cells ents, int e, emon.Port.Cells c, int at, int cnt) {
        // 1 when entry `e`'s request is the `cnt` cells at `at` of `c`, whole.
        if (emon.Port.CellsAt(ents, e + 5) != cnt) {
            return 0;
        }
        int i = 0;
        while (i < cnt) {
            if (emon.Port.CellsAt(ents, e + (6 + i)) != emon.Port.CellsAt(c, at + i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
    public static int TrIndex(emon.Transcriptctx.Tr t) {
        // Build the replay map over the entries: keyed by the WHOLE request record. Of two entries of one request the later is the map's.
        int size = 16;
        int e = 0;
        while (size < (2 * t.Nents)) {
            size *= 2;
        }
        emon.Port.CellsDrop(t.Idx, 0);
        int i = 0;
        while (i < size) {
            emon.Port.CellsPush(t.Idx, 0);
            i += 1;
        }
        t.Mask = size - 1;
        while (e < emon.Port.CellsLen(t.Ents)) {
            int rl = emon.Port.CellsAt(t.Ents, e + 5);
            emon.Port.CellsDrop(t.Tmp, 0);
            int i = 0;
            while (i < rl) {
                int v = emon.Port.CellsAt(t.Ents, e + (6 + i));
                emon.Port.CellsPush(t.Tmp, v);
                i += 1;
            }
            int h = TrHash(t.Tmp, 0, rl);
            int s = h & t.Mask;
            int placed = 0;
            while (placed == 0) {
                int cur = emon.Port.CellsAt(t.Idx, s);
                if (cur == 0) {
                    emon.Port.CellsSet(t.Idx, s, e + 1);
                    placed = 1;
                } else if (TrKeyEq(t.Ents, cur - 1, t.Tmp, 0, rl) == 1) {
                    emon.Port.CellsSet(t.Idx, s, e + 1);
                    placed = 1;
                } else {
                    s = (s + 1) & t.Mask;
                }
            }
            e += emon.Port.CellsAt(t.Ents, e);
        }
        return 0;
    }
    public static int TrFind(emon.Transcriptctx.Tr t, emon.Port.Cells c, int at, int cnt) {
        // The entry whose request is the `cnt` cells at `at` of `c`, whole: where it starts in `ents`, or -1 (a miss; also when `tr-index` has not run).
        if (t.Mask == 0) {
            return -1;
        }
        int s = TrHash(c, at, cnt) & t.Mask;
        while (0 < 1) {
            int cur = emon.Port.CellsAt(t.Idx, s);
            if (cur == 0) {
                return -1;
            }
            if (TrKeyEq(t.Ents, cur - 1, c, at, cnt) == 1) {
                return cur - 1;
            }
            s = (s + 1) & t.Mask;
        }
        return -1;
    }
    public static int TrTake(emon.Transcriptctx.Tr t, emon.Port.Cells c, int at, int cnt) {
        // `tr-find`, and the entry is marked used: a replay asked for it.
        int e = TrFind(t, c, at, cnt);
        if (e >= 0) {
            emon.Port.CellsSet(t.Ents, e + 3, 1);
        }
        return e;
    }
    public static int TrUnused(emon.Transcriptctx.Tr t) {
        // How many entries no replay asked for.
        int n = emon.Port.CellsLen(t.Ents);
        int e = 0;
        int k = 0;
        while (e < n) {
            if (emon.Port.CellsAt(t.Ents, e + 3) == 0) {
                k += 1;
            }
            e += emon.Port.CellsAt(t.Ents, e);
        }
        return k;
    }
    public static int TrUnusedMsg(emon.Transcriptctx.Tr t, System.Text.StringBuilder @out) {
        // `transcript-bad`'s sentence for a replay that left entries unasked: `3 recorded entries were never asked for`.
        emon.Port.TextI32(@out, TrUnused(t));
        emon.Port.TextAscii(@out, " ");
        return TbEmitName(@out, TbUnused());
    }
    public static int TrMissMsg(emon.Port.Cells c, int at, int cnt, System.Text.StringBuilder @out) {
        // `transcript-miss`'s sentence: `no answer recorded for request [6 1 2 ...]`.
        emon.Port.TextAscii(@out, "no answer recorded for request ");
        return TwInts(@out, c, at, cnt);
    }
    internal static int TwPairs(System.Text.StringBuilder @out, emon.Port.Cells c) {
        // `[index:length ...]`.
        int n = emon.Port.CellsLen(c);
        int i = 0;
        emon.Port.TextAscii(@out, "[");
        while (i < n) {
            if (i > 0) {
                emon.Port.TextAscii(@out, " ");
            }
            emon.Port.TextI32(@out, emon.Port.CellsAt(c, i));
            emon.Port.TextAscii(@out, ":");
            emon.Port.TextI32(@out, emon.Port.CellsAt(c, i + 1));
            i += 2;
        }
        emon.Port.TextAscii(@out, "]");
        return n;
    }
    public static int TrCheckInputs(emon.Transcriptctx.Tr t, emon.Port.Cells want, System.Text.StringBuilder @out) {
        // A replay is given the inputs the recording saw: the same count, the same lengths. 0, or `tb-inputs` with its sentence in `out`.
        int n = emon.Port.CellsLen(t.Inputs);
        int same = 1;
        int i = 0;
        if (n != emon.Port.CellsLen(want)) {
            same = 0;
        }
        while ((same == 1) && (i < n)) {
            if (emon.Port.CellsAt(t.Inputs, i) != emon.Port.CellsAt(want, i)) {
                same = 0;
            }
            i += 1;
        }
        if (same == 1) {
            return 0;
        }
        TbEmitName(@out, TbInputs());
        emon.Port.TextAscii(@out, ": ");
        TwPairs(@out, t.Inputs);
        emon.Port.TextAscii(@out, ", not ");
        TwPairs(@out, want);
        return TbInputs();
    }
    public static int TrNInputs(emon.Transcriptctx.Tr t) {
        return emon.Port.CellsLen(t.Inputs) / 2;
    }
    public static int TrInIndex(emon.Transcriptctx.Tr t, int i) {
        return emon.Port.CellsAt(t.Inputs, 2 * i);
    }
    public static int TrInLength(emon.Transcriptctx.Tr t, int i) {
        return emon.Port.CellsAt(t.Inputs, (2 * i) + 1);
    }
    public static int TrPMore(emon.Transcriptctx.Tr t, int p) {
        if (p < emon.Port.CellsLen(t.Prod)) {
            return 1;
        }
        return 0;
    }
    public static int TrPNext(emon.Transcriptctx.Tr t, int p) {
        // The producer pair after the one at `p` (the first is at 0).
        int kn = emon.Port.CellsAt(t.Prod, p);
        int vn = emon.Port.CellsAt(t.Prod, p + (kn + 1));
        return p + (kn + (vn + 2));
    }
    public static int TrPKey(emon.Transcriptctx.Tr t, int p, System.Text.StringBuilder @out) {
        int kn = emon.Port.CellsAt(t.Prod, p);
        return TwCps(@out, t.Prod, p + 1, kn, 0);
    }
    public static int TrPVal(emon.Transcriptctx.Tr t, int p, System.Text.StringBuilder @out) {
        int kn = emon.Port.CellsAt(t.Prod, p);
        int vn = emon.Port.CellsAt(t.Prod, p + (kn + 1));
        return TwCps(@out, t.Prod, p + (kn + 2), vn, 0);
    }
    public static int TrEMore(emon.Transcriptctx.Tr t, int e) {
        if (e < emon.Port.CellsLen(t.Ents)) {
            return 1;
        }
        return 0;
    }
    public static int TrENext(emon.Transcriptctx.Tr t, int e) {
        return e + emon.Port.CellsAt(t.Ents, e);
    }
    public static int TrERound(emon.Transcriptctx.Tr t, int e) {
        return emon.Port.CellsAt(t.Ents, e + 1);
    }
    public static int TrEN(emon.Transcriptctx.Tr t, int e) {
        return emon.Port.CellsAt(t.Ents, e + 4);
    }
    public static int TrEReq(emon.Transcriptctx.Tr t, int e) {
        return e + 6;
    }
    public static int TrEReqLen(emon.Transcriptctx.Tr t, int e) {
        return emon.Port.CellsAt(t.Ents, e + 5);
    }
    public static int TrEAns(emon.Transcriptctx.Tr t, int e) {
        return e + (6 + emon.Port.CellsAt(t.Ents, e + 5));
    }
    public static int TrEAnsLen(emon.Transcriptctx.Tr t, int e) {
        return emon.Port.CellsAt(t.Ents, e) - (6 + emon.Port.CellsAt(t.Ents, e + 5));
    }
    public static int TrECell(emon.Transcriptctx.Tr t, int at) {
        return emon.Port.CellsAt(t.Ents, at);
    }
    public static int TrEHasBitmap(emon.Transcriptctx.Tr t, int e) {
        if (emon.Port.CellsAt(t.Ents, e + 2) != 0) {
            return 1;
        }
        return 0;
    }
    public static int TrEBitmapName(emon.Transcriptctx.Tr t, int e, System.Text.StringBuilder @out) {
        // The file name of the entry's bitmap: as a file read named it, or as `tr-write` names it for an entry the host added. 0 when there is none.
        int bm = emon.Port.CellsAt(t.Ents, e + 2);
        if (bm == 0) {
            return 0;
        }
        if (bm < 0) {
            TrBitmapName(emon.Port.CellsAt(t.Ents, e + 4), @out);
            return 1;
        }
        int n = emon.Port.CellsAt(t.Names, bm - 1);
        TwCps(@out, t.Names, bm, n, 0);
        return 1;
    }
}
